def _import_cpva_client():
    """Load the shared CPVA client (sibling cpva_client.py). Reuses an
    already-loaded instance so every tool (and re-exec'd module copy) shares
    one connection pool and one day cache."""
    import sys as _sys
    import importlib.util as _ilu
    mod = _sys.modules.get("cpva_client")
    if mod is not None:
        return mod
    p = Path(__file__).resolve().parent / "cpva_client.py"
    spec = _ilu.spec_from_file_location("cpva_client", p)
    mod = _ilu.module_from_spec(spec)
    _sys.modules["cpva_client"] = mod   # register BEFORE exec (re-entrancy safe)
    spec.loader.exec_module(mod)
    return mod


cpva = _import_cpva_client()


def _import_img_scale():
    """Load the shared intensity-scale helper (sibling img_scale.py) the same way as
    cpva_client: one instance per process, registered before exec. It owns what an
    intensity MEANS, so the Slider, Finder and Shot Finder cannot drift apart on it."""
    import sys as _sys
    import importlib.util as _ilu
    mod = _sys.modules.get("img_scale")
    if mod is not None:
        return mod
    p = Path(__file__).resolve().parent / "img_scale.py"
    spec = _ilu.spec_from_file_location("img_scale", p)
    mod = _ilu.module_from_spec(spec)
    _sys.modules["img_scale"] = mod     # register BEFORE exec (re-entrancy safe)
    spec.loader.exec_module(mod)
    return mod


img_scale = _import_img_scale()


def _import_daypicker():
    """Load the shared day/time picker (sibling daypicker.py), same rule again:
    one instance per process, registered before exec. It owns HOW A DAY AND A TIME
    WINDOW ARE PICKED — the calendar, the click rules, the per-day table — so no
    tab can grow a calendar of its own again.

    Three locations are searched because a built app has no single answer. Next to
    this file means _internal, and _internal never survives the trip to the
    share: copying a program there does not bring its _internal at all, and
    "Deploy Libraries" (Dev Tools/dt_core.py) fills the destination's one from a
    single shared runtime library, deleting whatever that library does not have.
    daypicker.py is not in it and cannot be. The copy compiled into the exe
    (build_config.json -> hidden_imports) and the loose file the deploy drops
    beside the exe are the fallbacks."""
    import sys as _sys
    import importlib
    import importlib.util as _ilu
    mod = _sys.modules.get("daypicker")
    if mod is not None:
        return mod

    if getattr(_sys, "frozen", False):
        try:
            return importlib.import_module("daypicker")   # compiled into the exe
        except ImportError:
            pass

    tried: list = []
    for _d in (str(Path(__file__).resolve().parent),
               getattr(_sys, "_MEIPASS", ""),
               os.path.dirname(os.path.abspath(_sys.executable))):
        if not _d:
            continue
        p = os.path.join(_d, "daypicker.py")
        if p in tried:
            continue
        tried.append(p)
        if not os.path.isfile(p):
            continue
        spec = _ilu.spec_from_file_location("daypicker", p)
        mod = _ilu.module_from_spec(spec)
        _sys.modules["daypicker"] = mod    # register BEFORE exec (re-entrancy safe)
        try:
            spec.loader.exec_module(mod)
        except Exception:
            _sys.modules.pop("daypicker", None)
            raise
        return mod

    try:
        return importlib.import_module("daypicker")
    except ImportError:
        pass
    raise RuntimeError(
        "daypicker.py was not found. Looked in:\n  " + "\n  ".join(tried)
        + "\nand in the modules compiled into the program itself. A built copy "
          "needs 'daypicker' in build_config.json -> hidden_imports."
    )


daypicker = _import_daypicker()

CPVA_BASE_URL = cpva.CPVA_BASE_URL

