        sc_topn_row = QHBoxLayout()
        sc_topn_row.addWidget(QLabel("Show top intensity:"))
        self._sc_topn_sb = QSpinBox()
        self._sc_topn_sb.setRange(0, 9999)
        self._sc_topn_sb.setValue(0)
        self._sc_topn_sb.setFixedWidth(70)
